// Валидация данных от Apify
const items = $input.all();

if (!items || items.length === 0) {
  console.log('⚠️ Apify не вернул данные');
  return [];
}

const validItems = items.filter(item => {
  const data = item.json;

  // Проверяем обязательные поля
  if (!data.url) {
    console.log('⚠️ Пост без URL, пропускаем');
    return false;
  }

  // Проверяем что есть caption или media
  if (!data.caption && !data.media_url) {
    console.log('⚠️ Пост без контента, пропускаем');
    return false;
  }

  return true;
});

console.log(`✅ Валидация: ${validItems.length} из ${items.length} постов прошли проверку`);

return validItems;

// Фильтруем посты которые уже есть в базе
const posts = $input.all();
const supabase_url = 'https://pyscczcuersdjvpmkiec.supabase.co';
const service_key = '{{ $env.VITE_SUPABASE_SERVICE_ROLE_KEY }}';

// Получаем URL из базы (последние 30 дней)
const response = await fetch(
  `${supabase_url}/rest/v1/competitor_posts?select=post_url&created_at=gte.${new Date(Date.now() - 30*24*60*60*1000).toISOString()}`,
  {
    headers: {
      'apikey': service_key,
      'Authorization': `Bearer ${service_key}`
    }
  }
);

const existingUrls = await response.json();
const existingUrlSet = new Set(existingUrls.map(item => item.post_url));

// Фильтруем новые посты
const newPosts = posts.filter(post => {
  const url = post.json.url;
  if (existingUrlSet.has(url)) {
    console.log(`⏭️ Пост уже обработан: ${url}`);
    return false;
  }
  return true;
});

console.log(`✅ Новых постов: ${newPosts.length} из ${posts.length}`);

if (newPosts.length === 0) {
  console.log('ℹ️ Все посты уже обработаны, пропускаем AI анализ');
}

return newPosts;

// Безопасный парсинг JSON от Claude
const items = $input.all();

const parsed = items.map(item => {
  const claudeOutput = item.json.output || '';

  // Попытка извлечь JSON из ответа
  let parsedData = {
    analysis: 'Не удалось распарсить',
    script: 'Не удалось распарсить',
    score: 0
  };

  try {
    // Ищем JSON в ответе (может быть обернут в markdown)
    const jsonMatch = claudeOutput.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const jsonStr = jsonMatch[0];
      parsedData = JSON.parse(jsonStr);
      console.log('✅ JSON успешно распарсен');
    } else {
      console.log('⚠️ JSON не найден в ответе, используем весь текст');
      parsedData.script = claudeOutput;
    }
  } catch (error) {
    console.log('⚠️ Ошибка парсинга JSON:', error.message);
    // Fallback: используем regex как запасной вариант
    const analysisMatch = claudeOutput.match(/"analysis":\s*"(.+?)"/s);
    const scriptMatch = claudeOutput.match(/"script":\s*"(.+?)"/s);
    const scoreMatch = claudeOutput.match(/"score":\s*(\d+)/);

    if (analysisMatch) parsedData.analysis = analysisMatch[1];
    if (scriptMatch) parsedData.script = scriptMatch[1];
    if (scoreMatch) parsedData.score = parseInt(scoreMatch[1]);
  }

  return {
    json: {
      ...item.json,
      parsed_analysis: parsedData.analysis,
      parsed_script: parsedData.script,
      parsed_score: parsedData.score
    }
  };
});

return parsed;
